-- 大字段边界验证：query_sql / params_value 分片、边界、截断
-- AUDIT_MAIN_SQL_PAYLOAD_MAX=1023
-- AUDIT_MAIN_PARAMS_PAYLOAD_MAX=1023
-- AUDIT_FRAGMENT_PAYLOAD_MAX=1023
-- AUDIT_MAX_FRAGMENTS_PER_FIELD=16
-- AUDIT_SQL_CAPTURE_MAX=17391
-- AUDIT_PARAMS_CAPTURE_MAX=17391
CREATE DATABASE IF NOT EXISTS ebpf_audit_large_sql_test;
use ebpf_audit_large_sql_test;
DROP TABLE IF EXISTS ebpf_audit_large_sql_test.large_sql_case;
CREATE TABLE ebpf_audit_large_sql_test.large_sql_case (id INT NOT NULL, c LONGTEXT, PRIMARY KEY (id));
INSERT INTO ebpf_audit_large_sql_test.large_sql_case (id, c) VALUES (1, 'seed');

-- 普通文本协议 query_sql 边界：<= AUDIT_SQL_CAPTURE_MAX 应可被 check_audit_sql 精确匹配
-- CASE text query_sql main_below: query_sql_len=1022
SELECT 'EBPF_QSQL_MAIN_BELOW_1022_';
-- CASE text query_sql main_boundary: query_sql_len=1023
SELECT 'EBPF_QSQL_MAIN_BOUNDARY_1023_';
-- CASE text query_sql first_fragment: query_sql_len=1024
SELECT 'EBPF_QSQL_FIRST_FRAGMENT_1024_';
-- CASE text query_sql one_fragment_boundary: query_sql_len=2046
SELECT 'EBPF_QSQL_ONE_FRAGMENT_BOUNDARY_2046_';
-- CASE text query_sql two_fragments: query_sql_len=2047
SELECT 'EBPF_QSQL_TWO_FRAGMENTS_2047_';
-- CASE text query_sql capture_boundary: query_sql_len=17391
SELECT 'EBPF_QSQL_CAPTURE_BOUNDARY_17391_';
-- CASE text query_sql truncated:
-- query_sql_len=17392
SELECT 'EBPF_QSQL_TRUNCATED_17392_
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
GGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGGG
';

-- PS 协议 query_sql 边界：EXECUTE 记录应是 prepared 原 SQL（带 ? 占位），不是 EXECUTE 命令
-- CASE ps query_sql main_boundary: prepared_query_sql_len=1023
PREPARE ps_qsql_main_boundary FROM 'INSERT INTO ebpf_audit_large_sql_test.large_sql_case (id, c) VALUES (11023, ''EBPF_PS_QSQL_MAIN_BOUNDARY_1023_'')';
EXECUTE ps_qsql_main_boundary;
DEALLOCATE PREPARE ps_qsql_main_boundary;
-- CASE ps query_sql first_fragment: prepared_query_sql_len=1024
PREPARE ps_qsql_first_fragment FROM 'INSERT INTO ebpf_audit_large_sql_test.large_sql_case (id, c) VALUES (11024, ''EBPF_PS_QSQL_FIRST_FRAGMENT_1024_'')';
EXECUTE ps_qsql_first_fragment;
DEALLOCATE PREPARE ps_qsql_first_fragment;
-- CASE ps query_sql capture_boundary: prepared_query_sql_len=17391
PREPARE ps_qsql_capture_boundary FROM 'INSERT INTO ebpf_audit_large_sql_test.large_sql_case (id, c) VALUES (17391, ''EBPF_PS_QSQL_CAPTURE_BOUNDARY_17391_'')';
EXECUTE ps_qsql_capture_boundary;
DEALLOCATE PREPARE ps_qsql_capture_boundary;
-- CASE ps query_sql truncated: prepared_query_sql_len=17392
PREPARE ps_qsql_truncated FROM 'INSERT INTO ebpf_audit_large_sql_test.large_sql_case (id, c) VALUES (17392, ''EBPF_PS_QSQL_TRUNCATED_17392_'')';
EXECUTE ps_qsql_truncated;
DEALLOCATE PREPARE ps_qsql_truncated;

-- PS 协议 params_value 边界：query_sql 必须是完整 prepared SQL。不要用 SELECT ? 这种不完整语句。
-- CASE ps params_value main_boundary: params_value_len=1023
PREPARE ps_param_main_boundary FROM 'SELECT ? FROM ebpf_audit_large_sql_test.large_sql_case WHERE id = 1';
SET @p = CONCAT('EBPF_PARAM_MAIN_BOUNDARY_1023_', REPEAT('P', 993));
EXECUTE ps_param_main_boundary USING @p;
DEALLOCATE PREPARE ps_param_main_boundary;
-- CASE ps params_value first_fragment: params_value_len=1024
PREPARE ps_param_first_fragment FROM 'SELECT ? FROM ebpf_audit_large_sql_test.large_sql_case WHERE id = 1';
SET @p = CONCAT('EBPF_PARAM_FIRST_FRAGMENT_1024_', REPEAT('Q', 993));
EXECUTE ps_param_first_fragment USING @p;
DEALLOCATE PREPARE ps_param_first_fragment;
-- CASE ps params_value capture_boundary: params_value_len=17391
PREPARE ps_param_capture_boundary FROM 'SELECT ? FROM ebpf_audit_large_sql_test.large_sql_case WHERE id = 1';
SET @p = CONCAT('EBPF_PARAM_CAPTURE_BOUNDARY_17391_', REPEAT('R', 17357));
EXECUTE ps_param_capture_boundary USING @p;
DEALLOCATE PREPARE ps_param_capture_boundary;
-- CASE ps params_value truncated: params_value_len=17392
PREPARE ps_param_truncated FROM 'SELECT ? FROM ebpf_audit_large_sql_test.large_sql_case WHERE id = 1';
SET @p = CONCAT('EBPF_PARAM_TRUNCATED_17392_', REPEAT('S', 17365));
EXECUTE ps_param_truncated USING @p;
DEALLOCATE PREPARE ps_param_truncated;
